    29    note.p_align = 4;
    30
    31    dl_phdr_info info = {};
    32    info.dlpi_name = "test";
    33    info.dlpi_addr = reinterpret_cast<ElfW(Addr)>(data);
    34    info.dlpi_phdr = &note;
    35    info.dlpi_phnum = 1;
    36
    37    tcmalloc::tcmalloc_internal::GetBuildId(&info);
    38  #endif  // defined(__linux__)
    39    return 0;
    40  }

