    51  // Returns the Phdr of the first segment of the given type.
    52  const ElfW(Phdr) *
    53      GetFirstSegment(const dl_phdr_info* const info, const int segment_type) {
    54    for (int i = 0; i < info->dlpi_phnum; ++i) {
    55      if (info->dlpi_phdr[i].p_type == segment_type) {
    56        return &info->dlpi_phdr[i];
    57      }
    58    }
    59    return nullptr;
    60  }
