    62  // Return DT_SONAME for the given image.  If there is no PT_DYNAMIC or if
    63  // PT_DYNAMIC does not contain DT_SONAME, return nullptr.
    64  static const char* GetSoName(const dl_phdr_info* const info) {
    65    const ElfW(Phdr)* const pt_dynamic = GetFirstSegment(info, PT_DYNAMIC);
    66    if (pt_dynamic == nullptr) {
    67      return nullptr;
    68    }
    69    const ElfW(Dyn)* dyn =
    70        reinterpret_cast<ElfW(Dyn)*>(info->dlpi_addr + pt_dynamic->p_vaddr);
    71    const ElfW(Dyn)* dt_strtab = nullptr;
    72    const ElfW(Dyn)* dt_strsz = nullptr;
    73    const ElfW(Dyn)* dt_soname = nullptr;
    74    for (; dyn->d_tag != DT_NULL; ++dyn) {
    75      if (dyn->d_tag == DT_SONAME) {
    76        dt_soname = dyn;
    77      } else if (dyn->d_tag == DT_STRTAB) {
    78        dt_strtab = dyn;
    79      } else if (dyn->d_tag == DT_STRSZ) {
    80        dt_strsz = dyn;
    81      }
    82    }
    83    if (dt_soname == nullptr) {
    84      return nullptr;
    85    }
    86    CHECK_CONDITION(dt_strtab != nullptr);
    87    CHECK_CONDITION(dt_strsz != nullptr);
    88    const char* const strtab =
    89        reinterpret_cast<char*>(info->dlpi_addr + dt_strtab->d_un.d_val);
    90    CHECK_CONDITION(dt_soname->d_un.d_val < dt_strsz->d_un.d_val);
    91    return strtab + dt_soname->d_un.d_val;
    92  }
    93  #endif  // defined(__linux__)
