    95  struct SampleMergedData {
    96    int64_t count = 0;
    97    int64_t sum = 0;
    98    std::optional<size_t> resident_size;
    99    std::optional<size_t> swapped_size;
   100  };
   101
   102  // The equality and hash methods of Profile::Sample only use a subset of its
   103  // member fields.
   104  struct SampleEqWithSubFields {
   105    bool operator()(const Profile::Sample& a, const Profile::Sample& b) const {
   106      auto fields = [](const Profile::Sample& s) {
   107        return std::tie(s.depth, s.requested_size, s.requested_alignment,
   108                        s.requested_size_returning, s.allocated_size,
   109                        s.access_hint, s.access_allocated, s.guarded_status);
   110      };
   111      return fields(a) == fields(b) &&
   112             std::equal(a.stack, a.stack + a.depth, b.stack, b.stack + b.depth);
   113    }
   114  };
   115
   116  struct SampleHashWithSubFields {
   117    size_t operator()(const Profile::Sample& s) const {
   118      return absl::HashOf(absl::MakeConstSpan(s.stack, s.depth), s.depth,
   119                          s.requested_size, s.requested_alignment,
   120                          s.requested_size_returning, s.allocated_size,
   121                          s.access_hint, s.access_allocated, s.guarded_status);
   122    }
   123  };
   124
   125  using SampleMergedMap =
   126      absl::flat_hash_map<const tcmalloc::Profile::Sample, SampleMergedData,
   127                          SampleHashWithSubFields, SampleEqWithSubFields>;
   128
   129  SampleMergedMap MergeProfileSamplesAndMaybeGetResidencyInfo(
   130      const tcmalloc::Profile& profile) {
   131    SampleMergedMap map;
   132    // Used to populate residency info in heap profile.
   133    std::optional<Residency> residency;
   134
   135    if (profile.Type() == ProfileType::kHeap) {
   136      residency.emplace();
   137    }
   138    profile.Iterate([&](const tcmalloc::Profile::Sample& entry) {
   139      SampleMergedData& data = map[entry];
   140      data.count += entry.count;
   141      data.sum += entry.sum;
   142      if (residency.has_value()) {
   143        auto residency_info =
   144            residency->Get(entry.span_start_address, entry.allocated_size);
   145        // As long as `residency_info` provides data in some samples, the merged
   146        // data will have their sums.
   147        // NOTE: The data here is comparable to `tcmalloc::Profile::Sample::sum`,
   148        // not to `tcmalloc::Profile::Sample::requested_size` (it's pre-multiplied
   149        // by count and represents all of the resident memory).
   150        if (residency_info.has_value()) {
   151          size_t resident_size = entry.count * residency_info->bytes_resident;
   152          size_t swapped_size = entry.count * residency_info->bytes_swapped;
   153          if (!data.resident_size.has_value()) {
   154            data.resident_size = resident_size;
   155            data.swapped_size = swapped_size;
   156          } else {
   157            data.resident_size.value() += resident_size;
   158            data.swapped_size.value() += swapped_size;
   159          }
   160        }
   161      }
   162    });
   163    return map;
   164  }
