   168  #if defined(__linux__)
   169  // Extracts the linker provided build ID from the PT_NOTE segment found in info.
   170  //
   171  // On failure, returns an empty string.
   172  std::string GetBuildId(const dl_phdr_info* const info) {
   173    std::string result;
   174
   175    // pt_note contains entries (of type ElfW(Nhdr)) starting at
   176    //   info->dlpi_addr + pt_note->p_vaddr
   177    // with length
   178    //   pt_note->p_memsz
   179    //
   180    // The length of each entry is given by
   181    //   Align(sizeof(ElfW(Nhdr)) + nhdr->n_namesz) + Align(nhdr->n_descsz)
   182    for (int i = 0; i < info->dlpi_phnum; ++i) {
   183      const ElfW(Phdr)* pt_note = &info->dlpi_phdr[i];
   184      if (pt_note->p_type != PT_NOTE) continue;
   185
   186      const char* note =
   187          reinterpret_cast<char*>(info->dlpi_addr + pt_note->p_vaddr);
   188      const char* const last = note + pt_note->p_filesz;
   189      const ElfW(Word) align = pt_note->p_align;
   190      while (note < last) {
   191        const ElfW(Nhdr)* const nhdr = reinterpret_cast<const ElfW(Nhdr)*>(note);
   192        if (note + sizeof(*nhdr) > last) {
   193          // Corrupt PT_NOTE
   194          break;
   195        }
   196
   197        // Both the start and end of the descriptor are aligned by sh_addralign
   198        // (= p_align).
   199        const ElfW(Word) desc_start =
   200            (sizeof(*nhdr) + nhdr->n_namesz + align - 1) & -align;
   201        const ElfW(Word) size =
   202            desc_start + ((nhdr->n_descsz + align - 1) & -align);
   203
   204        // Beware of overflows / wrap-around.
   205        if (nhdr->n_namesz >= static_cast<ElfW(Word)>(-align) ||
   206            nhdr->n_descsz >= static_cast<ElfW(Word)>(-align) ||
   207            size < sizeof(*nhdr) || note + size > last) {
   208          // Corrupt PT_NOTE
   209          break;
   210        }
   211
   212        if (nhdr->n_type == NT_GNU_BUILD_ID) {
   213          const char* const note_name = note + sizeof(*nhdr);
   214          // n_namesz is the length of note_name.
   215          if (nhdr->n_namesz == 4 && memcmp(note_name, "GNU\0", 4) == 0) {
   216            if (!result.empty()) {
   217              // Repeated build-ids.  Ignore them.
   218              return "";
   219            }
   220            result = absl::BytesToHexString(
   221                absl::string_view(note + desc_start, nhdr->n_descsz));
   222          }
   223        }
   224        note += size;
   225      }
   226    }
   227
   228    return result;
   229  }
