    42  // ProfileBuilder manages building up a profile.proto instance and populating
    43  // common parts using the string/pointer table conventions expected by pprof.
    44  class ProfileBuilder {
    45   public:
    46    ProfileBuilder();
    47
    48    perftools::profiles::Profile& profile() { return *profile_; }
    49
    50    // Adds the current process mappings to the profile.
    51    void AddCurrentMappings();
    52
    53    // Adds a single mapping to the profile and to lookup cache.
    54    void AddMapping(uintptr_t memory_start, uintptr_t memory_limit,
    55                    uintptr_t file_offset, absl::string_view filename,
    56                    absl::string_view build_id);
    57
    58    // Interns sv in the profile's string table and returns the resulting ID.
    59    int InternString(absl::string_view sv);
    60    // Interns a location in the profile's location table and returns the
    61    // resulting ID.
    62    int InternLocation(const void* ptr);
    63
    64    // Interns a callstack and adds the IDs to the provided sample.
    65    void InternCallstack(absl::Span<const void* const> stack,
    66                         perftools::profiles::Sample& sample);
    67
    68    std::unique_ptr<perftools::profiles::Profile> Finalize() &&;
    69
    70   private:
    71    std::unique_ptr<perftools::profiles::Profile> profile_;
    72    // mappings_ stores the start address of each mapping in profile_->mapping()
    73    // to its index.
    74    absl::btree_map<uintptr_t, int> mappings_;
    75    absl::flat_hash_map<std::string, int> strings_;
    76    absl::flat_hash_map<uintptr_t, int> locations_;
    77  };
